import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [formData, setFormData] = useState({ day: 'Monday', grade: '', subject_id: '', time_slot: '', teacher_id: '' });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = () => {
    axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data));
    axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
    axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then(() => {
      fetchData();
      alert("Class Scheduled Successfully!");
    });
  };

  return (
    <div style={{ padding: '20px' }}>
      <h2>📅 Manage Classes</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
        <input type="text" placeholder="Day (e.g. Monday)" onChange={(e) => setFormData({...formData, day: e.target.value})} required />
        <input type="text" placeholder="Grade" onChange={(e) => setFormData({...formData, grade: e.target.value})} required />
        <input type="text" placeholder="Time (e.g. 3.00-5.00)" onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required />
        
        <select onChange={(e) => setFormData({...formData, subject_id: e.target.value})} required>
            <option value="">Select Subject</option>
            {subjects.map(s => <option key={s.id} value={s.id}>{s.subject_name}</option>)}
        </select>
        
        <select onChange={(e) => setFormData({...formData, teacher_id: e.target.value})} required>
            <option value="">Select Teacher</option>
            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
        </select>
        <button type="submit" style={{backgroundColor: '#15803d', color: 'white'}}>Save Class</button>
      </form>

      <table border="1" width="100%" style={{marginTop: '20px', borderCollapse: 'collapse'}}>
        <thead>
          <tr><th>Day</th><th>Grade</th><th>Subject</th><th>Teacher</th><th>Time</th></tr>
        </thead>
        <tbody>
          {classes.map(c => (
            <tr key={c.id}>
              <td>{c.day}</td><td>{c.grade}</td><td>{c.subject}</td><td>{c.teacher}</td><td>{c.time_slot}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
